def update(state, progress, message, **fields):
    with LOCK:
        STATUS.update(state=state,progress=progress,message=message,**fields)


def when(s):
    return dt.datetime.fromisoformat(s.replace('Z', '+00:00'))


def stamp(d):
    if isinstance(d, str): d=when(d)
    return d.astimezone(dt.timezone.utc).isoformat().replace('+00:00','Z')


def write_csv(name, rows):
    rows=list(rows);OUT.mkdir(parents=True,exist_ok=True)
    fields=list(dict.fromkeys(k for r in rows for k in r)) or ['no_data']
    with (OUT/(name+'.csv')).open('w',newline='',encoding='utf-8') as f:
        writer=csv.DictWriter(f,fieldnames=fields,extrasaction='raise')
        writer.writeheader();writer.writerows(rows)


def package():
    OUT.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(BUNDLE,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for p in sorted(OUT.glob('*.csv')):z.write(p,arcname=p.name)


def frozen():
    raw=zlib.decompress(base64.b85decode(FROZEN_B85))
    digest=hashlib.sha256(raw).hexdigest()
    if digest!=FROZEN_SHA256:raise RuntimeError('Embedded frozen input SHA256 mismatch')
    d=json.loads(raw)
    if len(d['baseline'])!=3029 or len(d['reference_ledgers'])!=4:
        raise RuntimeError('Unexpected frozen baseline/ledger counts')
    return d,digest


def fetch_chunk(start,end):
    if not TOKEN:raise RuntimeError('OANDA_TOKEN missing (read-only candles access only)')
    q=dict(price='M',granularity='M15',smooth='false',
           **{'from':stamp(start),'to':stamp(end),'includeFirst':'true'})
    response=requests.get(f'{API}/v3/instruments/{PAIR}/candles',
       params=q,headers={'Authorization':'Bearer '+TOKEN.strip()},timeout=85)
    if response.status_code>=400:
        description=response.text[:400]
        if response.status_code in (400,404) and any(phrase in description.lower()
                for phrase in ('no candles','no candle','no data')):
            return []  # OANDA may return an error for pre-listing history.
        raise RuntimeError(f'OANDA candles {response.status_code}: {description[:250]}')
    candles=[]
    for bar in response.json().get('candles',[]):
        if bar.get('complete',False):
            mid=bar['mid']
            candles.append((when(bar['time']),float(mid['o']),float(mid['h']),
                       float(mid['l']),float(mid['c'])))
    return candles


def fetch_history():
    start=when(CANDLE_FIRST_REQUEST); end=when(FETCH_UNTIL)
    cursor=start;seen={};part=0
    while cursor<end:
        nxt=min(cursor+dt.timedelta(days=35),end);part+=1
        for bar in fetch_chunk(cursor,nxt):
            if bar[0] <= when(ARCHIVE_LAST_CANDLE):seen[bar[0]]=bar
        cursor=nxt
        if part%8==1:
            update('fetch',min(8+part//3,25),f'AUD/JPY M15 historical chunk {part}: {stamp(cursor)}')
        if part%10==0:time.sleep(.03)
    bars=[seen[x] for x in sorted(seen)]
    if len(bars)!=CANDLE_COUNT or stamp(bars[-1][0])!=ARCHIVE_LAST_CANDLE:
        raise RuntimeError(f'Archived candle coverage mismatch: got {len(bars)}, last '
                           f'{stamp(bars[-1][0]) if bars else "NONE"}; expected '
                           f'{CANDLE_COUNT}, last {ARCHIVE_LAST_CANDLE}. STOP before parity.')
    return bars


def independent_signal_indices(bars, distance):
    # Causal indicators computed from the raw M15 candle tuple; not imported
    # from Pass 6. ATR14 Wilder seeded by mean of FIRST 14 true ranges.
    n=len(bars)
    o=np.fromiter((b[1] for b in bars),float,count=n)
    h=np.fromiter((b[2] for b in bars),float,count=n)
    l=np.fromiter((b[3] for b in bars),float,count=n)
    c=np.fromiter((b[4] for b in bars),float,count=n)
    true_range=np.maximum(h-l,np.maximum(abs(h-np.r_[c[0],c[:-1]]),
                                      abs(l-np.r_[c[0],c[:-1]])))
    atr=np.full(n,np.nan)
    atr[13]=np.mean(true_range[:14])
    for i in range(14,n):atr[i]=(13*atr[i-1]+true_range[i])/14
    prior_low=np.full(n,np.nan)
    dq=deque()
    for i in range(n):
        if i:
            j=i-1
            while dq and l[dq[-1]]>=l[j]:dq.pop()
            dq.append(j)
        while dq and dq[0]<i-60:dq.popleft()
        if i>=60:prior_low[i]=l[dq[0]]
    mom=np.full(n,np.nan)
    mom[193:]=(c[192:-1]-c[:-193])/atr[193:]
    prev_o=np.r_[np.nan,o[:-1]]
    prev_c=np.r_[np.nan,c[:-1]]
    engulf=(prev_c<prev_o)&(c>o)&(o<=prev_c)&(c>=prev_o)
    # The prior candle's body must be non-zero for BR>=1.00.
    engulf &= (prev_o-prev_c>0)&((c-o)>=(prev_o-prev_c))
    good=np.isfinite(atr)&(atr>0)&np.isfinite(mom)&np.isfinite(prior_low)
    close_to_low=np.full(n,np.inf)
    close_to_low[good]=abs(l[good]-prior_low[good])/atr[good]
    bodyatr=np.full(n,-np.inf);rangeatr=np.full(n,-np.inf)
    bodyatr[good]=(c[good]-o[good])/atr[good]
    rangeatr[good]=(h[good]-l[good])/atr[good]
    mask=(good&engulf&(close_to_low<=distance)&(bodyatr>=1.0)&
          (rangeatr>=1.80)&(mom>=.50))
    mask[:200]=False
    return np.flatnonzero(mask).tolist()


def independent_trade(bars,i,cost):
    signal=bars[i];ref=signal[4];stop=signal[3] - STOP_TICKS*TICK
    reference_risk=ref-stop
    if reference_risk<=0:return None
    target=ref+RR*reference_risk
    fill=ref+cost*PIP
    actual_risk=fill-stop
    if actual_risk<=0:return None
    for j in range(i+1,len(bars)):
        bar=bars[j]
        stop_hit=bar[3]<=stop;target_hit=bar[2]>=target
        if not (stop_hit or target_hit):continue
        if stop_hit and target_hit:
            # Closer to M15 open: high->TARGET; low/equal->STOP.
            reason=('TARGET' if abs(bar[2]-bar[1])<abs(bar[1]-bar[3])
                    else 'STOP')
        else:reason='STOP' if stop_hit else 'TARGET'
        price=stop if reason=='STOP' else target
        return dict(signal_index=i,exit_index=j,
            entry_time_utc=stamp(signal[0]),exit_time_utc=stamp(bar[0]),
            reference_entry=ref,historical_fill=fill,stop=stop,target=target,
            result_r=(price-fill)/actual_risk,exit_reason=reason,
            rr=RR,cost_pips=cost)
    return None


def independent_replay(bars, signals, cost):
    trades=[];p=0
    while p<len(signals):
        t=independent_trade(bars,signals[p],cost)
        if t is None:p+=1;continue
        trades.append(t)
        # [signal_index,exit_index) p0; exit-candle entry allowed.
        p=bisect.bisect_left(signals,t['exit_index'],lo=p+1)
    return trades


def parity(reference,actual):
    FIELDS=('signal_index','exit_index','entry_time_utc','exit_time_utc',
            'reference_entry','historical_fill','stop','target','result_r',
            'exit_reason','rr','cost_pips')
    if len(reference)!=len(actual):
        raise RuntimeError(f'Full accepted-ledger count mismatch {len(actual)} != {len(reference)}')
    for ix,(ref,got) in enumerate(zip(reference,actual)):
        for k in FIELDS:
            value=ref[k];observed=got[k]
            if k in ('signal_index','exit_index'):
                okay=int(value)==int(observed)
            elif k in ('reference_entry','historical_fill','stop','target','result_r','rr','cost_pips'):
                okay=math.isclose(float(value),float(observed),rel_tol=0,abs_tol=1e-8)
            else:okay=value==observed
            if not okay:
                raise RuntimeError(f'Full ledger parity row={ix} field={k}: '
                                   f'actual={observed} archived={value}')
    return dict(result='PASS',accepted_trades=len(actual),
         total_r=sum(x['result_r'] for x in actual),
         fields_checked=len(FIELDS)*len(actual))


def portfolio_trade(t):
    # Entry and exit are both the modelled M15 bar COMPLETION timestamps.
    return dict(sid=SID,pair=PAIR,side='BUY',tf='M15',rr=RR,
                signal=t['entry_time_utc'],
                entry=stamp(when(t['entry_time_utc'])+dt.timedelta(minutes=15)),
                exit=stamp(when(t['exit_time_utc'])+dt.timedelta(minutes=15)),
                r=float(t['result_r']))


def baseline_identity(t):
    return (t['sid'],t['pair'],t['side'],t['tf'],t['signal'],t['entry'],
            t['exit'],round(float(t['r']),9),float(t['rr']))


def equity(trades, audit=False):
    # Identical stated 27-strategy risk/event model, independently authored.
    events=[]
    for i,t in enumerate(trades):
        events.append((t['entry'],1,t['sid'],i,t))
        events.append((t['exit'],0,t['sid'],i,t))
    events.sort(key=lambda x:(x[0],x[1],x[2],x[3])) # EXITS first
    balance=100.;peak=100.;risk_total=0.;closed_dd=0.;floor_dd=0.
    max_open=0;max_open_risk=0.;active={};exits=[];audit_rows=[]
    overlap_any=0;overlap_audusd=0;overlap_jpy=0;overlap_eurjpy=0
    for date,kind,sid,idx,t in events:
        if kind==0:
            cash,_=active.pop(idx)
            risk_total-=cash
            balance+=cash*float(t['r'])
            if balance<=0:raise RuntimeError('Portfolio model equity <= 0')
            peak=max(peak,balance)
            closed_dd=min(closed_dd,100*(balance/peak-1))
            exits.append((date,balance,sid,float(t['r'])))
        else:
            cash=balance*(.0075 if sid=='EUR_JPY_M15_SHORT' else .01)
            if sid==SID:
                pairs=[v['pair'] for _,v in active.values()]
                overlap_any+=bool(pairs)
                overlap_audusd+='AUD_USD' in pairs
                overlap_jpy+=any(x in ('EUR_JPY','USD_JPY') for x in pairs)
                overlap_eurjpy+='EUR_JPY' in pairs
            active[idx]=(cash,t);risk_total+=cash
        max_open=max(max_open,len(active))
        max_open_risk=max(max_open_risk,100*risk_total/balance)
        floor_dd=min(floor_dd,100*((balance-risk_total)/peak-1))
        if audit:
            audit_rows.append(dict(event_time=date,event='EXIT' if kind==0 else 'ENTRY',
                sid=sid,balance=balance,open_positions=len(active),
                open_risk_pct=100*risk_total/balance,
                closed_dd_pct=100*(balance/peak-1),
                floor_dd_pct=100*((balance-risk_total)/peak-1)))
    return dict(balance=balance,closed_dd=closed_dd,floor_dd=floor_dd,
       max_open=max_open,max_open_risk=max_open_risk,exits=exits,
       overlap_any=overlap_any,overlap_audusd=overlap_audusd,
       overlap_jpy=overlap_jpy,overlap_eurjpy=overlap_eurjpy,
       audit_rows=audit_rows)


def check_baseline(b):
    if len(b)!=EXPECTED_BASE['count'] or len({x['sid'] for x in b})!=27:
        raise RuntimeError('Portfolio27 baseline count or strategy mismatch')
    if len({baseline_identity(t) for t in b})!=len(b):
        raise RuntimeError('Duplicate baseline trade identity')
    if any(t['pair']=='AUD_JPY' for t in b):
        raise RuntimeError('AUD/JPY exists in baseline: pair-gate rebuild required')
    sim=equity(b)
    years=(when(max(x['exit'] for x in b))-when(min(x['entry'] for x in b))).total_seconds()/(365.2425*86400)
    cagr=100*((sim['balance']/100)**(1/years)-1)
    tests=dict(count=len(b),strategies=len({x['sid'] for x in b}),cagr=cagr,
         closed_dd=sim['closed_dd'],floor_dd=sim['floor_dd'],ending_balance=sim['balance'])
    output=[]
    for field,expected in EXPECTED_BASE.items():
        actual=tests[field]
        okay=math.isclose(actual,expected,abs_tol=1e-6,rel_tol=1e-10)
        output.append(dict(field=field,expected=expected,actual=actual,
                           result='PASS' if okay else 'FAIL'))
        if not okay:raise RuntimeError(f'Portfolio27 parity {field}: {actual} != {expected}')
    return output,sim


def balance_at(sim,at):
    dates=[x[0] for x in sim['exits']]
    j=bisect.bisect_right(dates,stamp(at))-1
    return sim['exits'][j][1] if j>=0 else 100.


def portfolio_summary(name,trades,sim):
    first=min(when(x['entry']) for x in trades)
    last=max(when(x['exit']) for x in trades)
    years=(last-first).total_seconds()/(365.2425*86400)
    cand=[x for x in trades if x['sid']==SID]
    return dict(scenario=name,strategies=len({x['sid'] for x in trades}),trades=len(trades),
       candidate_trades=len(cand),candidate_r=sum(x['r'] for x in cand),
       weighted_r_equivalent=sum(x['r']*(.75 if x['sid']=='EUR_JPY_M15_SHORT' else 1.) for x in trades),
       historical_cagr_pct=100*((sim['balance']/100.)**(1/years)-1),
       balance_from_100=sim['balance'],max_closed_dd_pct=sim['closed_dd'],
       max_open_risk_floor_dd_pct=sim['floor_dd'],max_positions=sim['max_open'],
       max_open_risk_pct=sim['max_open_risk'],overlap_any=sim['overlap_any'],
       overlap_AUD_USD=sim['overlap_audusd'],overlap_JPY_pair=sim['overlap_jpy'],
       overlap_EUR_JPY=sim['overlap_eurjpy'],portfolio_cutoff=PORTFOLIO_CUTOFF)


def years_rows(scenario,sim):
    end=when(PORTFOLIO_CUTOFF)
    rows=[]
    for n in (1,2,3,5):
        start=end-dt.timedelta(days=365.2425*n)
        a=balance_at(sim,start);b=balance_at(sim,end)
        rows.append(dict(scenario=scenario,years=n,start=stamp(start),end=stamp(end),
                   total_pct=100*(b/a-1),annualised_pct=100*((b/a)**(1/n)-1)))
    return rows


def months_between(first,last):
    y,m=first.year,first.month
    while (y,m)<=(last.year,last.month):
        left=dt.datetime(y,m,1,tzinfo=dt.timezone.utc)
        ny,nm=(y+1,1) if m==12 else (y,m+1)
        right=dt.datetime(ny,nm,1,tzinfo=dt.timezone.utc)
        yield left,right
        y,m=ny,nm


def rolling_rows(scenario,sim,first):
    cutoff=when(PORTFOLIO_CUTOFF)
    months=[(left,right) for left,right in months_between(first,cutoff)
            if right<=cutoff] # exclude partial first? first month starts before first trade -> equity 100.
    rows=[]
    for n in (12,24,36):
        for j in range(n-1,len(months)):
            start=months[j-n+1][0];end=months[j][1]
            a=balance_at(sim,start);b=balance_at(sim,end)
            rows.append(dict(scenario=scenario,months=n,start=stamp(start),
                 end=stamp(end),compounded_return_pct=100*(b/a-1)))
    return rows


def rolling_summary(rows):
    groups=defaultdict(list)
    for x in rows:groups[(x['scenario'],x['months'])].append(x['compounded_return_pct'])
    return [dict(scenario=k[0],months=k[1],completed_windows=len(v),
           positive_pct=100*sum(x>0 for x in v)/len(v),worst_pct=min(v),
           median_pct=statistics.median(v),best_pct=max(v))
           for k,v in sorted(groups.items()) if v]


def standalone_rows(label,cost,ledger):
    rr=[x['result_r'] for x in ledger]
    equity_r=0.;top_r=0.;dd=0.;streak=0;max_streak=0
    for x in rr:
        equity_r+=x;top_r=max(top_r,equity_r);dd=min(dd,equity_r-top_r)
        streak=streak+1 if x<0 else 0;max_streak=max(max_streak,streak)
    wins=[x for x in rr if x>0];loss=[x for x in rr if x<0]
    return dict(geometry=label,cost_pips=cost,accepted_trades=len(rr),
        wins=len(wins),losses=len(loss),total_r=sum(rr),
        profit_factor=sum(wins)/-sum(loss) if loss else None,
        max_closed_drawdown_r=dd,longest_loss_streak=max_streak,
        pre2010_r=sum(x['result_r'] for x in ledger if x['entry_time_utc']<'2010-01-01'),
        from2010_r=sum(x['result_r'] for x in ledger if x['entry_time_utc']>='2010-01-01'),
        last2y_r=sum(x['result_r'] for x in ledger if x['entry_time_utc']>='2024-09-20'),
        last5y_r=sum(x['result_r'] for x in ledger if x['entry_time_utc']>='2021-09-20'))


def run():
    OUT.mkdir(parents=True,exist_ok=True)
    for file in OUT.glob('*.csv'):file.unlink()
    if BUNDLE.exists():BUNDLE.unlink()
    try:
        update('baseline',3,'Loading SHA256 frozen Pass6 + Portfolio27 inputs')
        archive,digest=frozen()
        baseline=archive['baseline']
        base_rows,base_sim=check_baseline(baseline)
        write_csv('baseline_parity',base_rows)
        update('fetch',7,'Fetching AUD/JPY midpoint M15 history through frozen Pass6 cutoff')
        bars=fetch_history()
        write_csv('coverage',[dict(candles=len(bars),first=stamp(bars[0][0]),
           last=stamp(bars[-1][0]),embedded_sha256=digest,portfolio_snapshot=PORTFOLIO_CUTOFF)])
        update('independent',34,'Independent ATR, engulfing, prior low and 192bar momentum')
        expected_by_name=archive['reference_ledgers']
        ledgers={};parity_rows=[];standalone=[];trades=[]
        for name,distance in DISTANCES:
            raw=independent_signal_indices(bars,distance)
            for cost in COSTS:
                key=f'{name}_{int(cost)}P'
                actual=independent_replay(bars,raw,cost)
                check=parity(expected_by_name[key],actual)
                parity_rows.append(dict(geometry=name,cost_pips=cost,
                                        raw_signals=len(raw),**check))
                ledgers[key]=actual
                standalone.append(standalone_rows(name,cost,actual))
                for t in actual:
                    trades.append(dict(geometry=name,**t))
            update('parity',45 if name=='CORE_D050' else 60,
                   f'{name} complete 2/4pip full accepted-ledger parity')
        write_csv('candidate_full_ledger_parity',parity_rows)
        write_csv('candidate_standalone',standalone)
        write_csv('candidate_accepted_ledgers',trades)
        # Portfolio snapshot must be a strict subset; no future entries or exits.
        update('portfolio',67,'Replaying 27→28 at historical cutoff and both cost assumptions')
        scenarios=[('BASELINE_27',baseline,base_sim)]
        for name,distance in DISTANCES:
            for cost in COSTS:
                k=f'{name}_{int(cost)}P'
                cand=[pt for t in ledgers[k] for pt in [portfolio_trade(t)]
                      if pt['exit']<=PORTFOLIO_CUTOFF]
                if any(t['pair']=='AUD_JPY' for t in baseline):
                    raise RuntimeError('Pair-gate cannot be inferred from accepted baseline')
                scenarios.append((k,baseline+cand,equity(baseline+cand)))
        first=min(when(x['entry']) for x in baseline)
        summary=[portfolio_summary(label,t,sim) for label,t,sim in scenarios]
        write_csv('portfolio_27_to_28',summary)
        periods=[];rolling=[];audit=[]
        for label,t,sim in scenarios:
            periods.extend(years_rows(label,sim))
            rolling.extend(rolling_rows(label,sim,first))
            # audit events are exported for independently inspecting risk accounting.
            if label!='BASELINE_27':
                for row in equity(t,True)['audit_rows']:
                    if row['sid']==SID:audit.append(dict(scenario=label,**row))
        write_csv('portfolio_last_1_2_3_5_years',periods)
        write_csv('portfolio_rolling_12_24_36_summary',rolling_summary(rolling))
        write_csv('portfolio_rolling_all_windows',rolling)
        write_csv('candidate_portfolio_event_audit',audit)
        write_csv('methodology',[
            dict(topic='scope',note='Offline research only. No live orders, no modifications or automatic approval.'),
            dict(topic='freeze',note='Exact engulf, LB60, absolute previous-low distance <=.50/.75 ATR, body>=1 ATR, range>=1.8 ATR, prior192-bar rise>=.5 ATR, RR3.5.'),
            dict(topic='full_ledger',note='Independent M15 signals and 2/4pip full 95/133 accepted ledgers match archived Pass6 field-by-field BEFORE portfolio metrics.'),
            dict(topic='pricing',note='OANDA midpoint data, assumed adverse +2/+4 pips (not empirical executable bid/ask). Same candle target/stop tie closer to open.'),
            dict(topic='entry_exit',note='Entry signal candle CLOSE; exit next-or-later bar CLOSE time; exit candle signal p0 eligible.'),
            dict(topic='pair_gate',note='No AUD_JPY trades in 3029-accepted Portfolio27; no pair collisions, no global max-position limit. Accepted incumbent ledgers therefore unchanged.'),
            dict(topic='risk',note='1% of realised equity at trade entry; EUR_JPY_M15_SHORT .75%; event exit before entry; open-risk floor conservative bound.'),
            dict(topic='periods',note='Baseline snapshot through 2026-09-20T18:29Z; candidate M15 run through Pass6 2026-09-24T09:45Z for strict independent parity; truncate only for portfolio.'),
            dict(topic='independence',note='Separate implementation, SAME previously mined historical period; not independently held-out forward evidence.'),
            dict(topic='live',note='Even positive 27→28 backtest requires real spread/slippage and prospectively observed fills before deployment.'),
        ])
        package()
        update('complete',100,'Full independent field parity and 27→28 historical comparison complete',
            candidate_full_ledger_parity='PASS',portfolio27_baseline='PASS',
            orders_supported=False,trading_enabled=False,
            result_path='/audjpy-m15-long-27to28/results')
    except Exception as ex:
        write_csv('error',[dict(error_type=type(ex).__name__,message=str(ex),
                                    traceback=traceback.format_exc())])
        package()
        update('error',100,f'{type(ex).__name__}: {ex}',
            traceback=traceback.format_exc(),orders_supported=False,trading_enabled=False)
        print(traceback.format_exc(),file=sys.stderr,flush=True)


if Flask is not None:
    app=Flask(__name__)
    @app.get('/')
    def home():return jsonify(service='AUD/JPY frozen independent + 27to28',
       status='/audjpy-m15-long-27to28/status',
       results='/audjpy-m15-long-27to28/results',orders_supported=False,trading_enabled=False)
    @app.get('/audjpy-m15-long-27to28/status')
    def status_endpoint():return jsonify(dict(STATUS))
    @app.get('/audjpy-m15-long-27to28/results')
    def results_endpoint():
        if not BUNDLE.exists():return jsonify(error='Results not ready',status=STATUS),409
        return send_file(BUNDLE,as_attachment=True,download_name=BUNDLE.name)

if __name__=='__main__':
    if '--offline-self-test' in sys.argv:
        print('frozen input SHA256:',frozen()[1]);print('Portfolio27 baseline parity:',len(check_baseline(frozen()[0]['baseline'])[0]),'PASS')
        raise SystemExit(0)
    if '--run-once' in sys.argv:
        run()
        raise SystemExit(0 if STATUS['state']=='complete' else 1)
    if Flask is None:raise RuntimeError('Install flask or run --run-once')
    threading.Thread(target=run,daemon=True,name='audjpy-independent').start()
    app.run(host='0.0.0.0',port=int(os.getenv('PORT','8080')),
            debug=False,use_reloader=False)
